Actually, here's another simpler approach for proxy support. We can use the `socks` package directly:

```javascript
import { SocksClient } from 'socks'

function createProxyConnect(proxyUrl, targetHost, targetPort) {
  const url = new URL(proxyUrl)
  const proxyType = url.protocol === 'socks5:' ? 5 : 4

  return (client) => {
    SocksClient.createConnection({
      proxy: {
        host: url.hostname,
        port: parseInt(url.port || (proxyType === 5 ? 1080 : 1080)),
        type: proxyType,
        userId: url.username || undefined,
        password: url.password || undefined,
      },
      command: 'connect',
      destination: { host: targetHost, port: targetPort }
    }).then(info => {
      client.setSocket(info.socket)
      client.emit('connect')
    }).catch(err => {
      console.error('[!] Proxy connection failed:', err.message)
      client.emit('error', err)
    })
  }
}
```

